// plural helpers for the fr, ru and ar sentences (a fraction such as 3.5 rooms takes the "few" form)
const num = (n) => Number(String(n).replace(',', '.'));
const frPl = (n, one, many) => n + ' ' + (num(n) >= 2 ? many : one);
const ruPl = (n, one, few, many) => {
  const v = num(n);
  if (!Number.isInteger(v)) return n + ' ' + few;
  const a = Math.abs(v) % 100, b = a % 10;
  return n + ' ' + (a > 10 && a < 20 ? many : b === 1 ? one : b >= 2 && b <= 4 ? few : many);
};
const arPl = (n, one, two, few, many) => {
  const v = num(n);
  if (v === 1) return one;
  if (v === 2) return two;
  return n + ' ' + ((v >= 3 && v <= 10) || !Number.isInteger(v) ? few : many);
};
