// HAD-792: five languages; the additions of that work live in stringsx.js and are merged over the same tables
export const strings = (lang) => {
  const L = STRINGS[lang] ? lang : lang && lang !== 'he' ? 'en' : 'he';
  return { ...STRINGS.he, ...MORE.he, ...(L !== 'he' ? STRINGS[L] : {}), ...(L !== 'he' ? MORE[L] : {}), lang: L };
};
